data.grammar_fragment:
expr<T> : <0.5> CASE WHEN "true" THEN expr<T> ELSE expr<T> END ;
expr<text> : <0.5> COALESCE "(" @lit(text) "," ( expr<text> COLLATE "POSIX" ) ")"
           | <0.5> NULLIF "(" expr<text> "," ( "NULL::text" COLLATE "POSIX" ) ")" ;

seeds:
CREATE TABLE t_simpl (a text NOT NULL, b text);
INSERT INTO t_simpl VALUES ('foo'), ('FOO');
SELECT count(*) FROM (SELECT COALESCE(a, b COLLATE "POSIX") FROM t_simpl GROUP BY 1) q;
